from collections import Counter

def get_exponents(n):
    exponents = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            exponents.append(count)
        d += 1
    if temp > 1:
        exponents.append(1)
    return sorted(exponents)

