import itertools

def final_solve():
    solutions = []
    for k in range(1, 10):
        for a_tuple in itertools.combinations_with_replacement(range(1, 11), k):
            P = 1
            for a in a_tuple:
                P *= (12 * a + 1)
            exponents = get_exponents(P)
            if exponents == sorted(a_tuple):
                solutions.append((P, list(a_tuple)))
    return sorted(list(set([s[0] for s in solutions])))

